import{_ as l,a0 as o,w as r,s as d,I as e,x as s,a1 as a,A as p,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"在 Linux 上用 SELinux 或 AppArmor 實現強制訪問控制（MAC） | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上用 SELinux 或 AppArmor 實現強制訪問控制（MAC） | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上用 SELinux 或 AppArmor 實現強制訪問控制（MAC） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上用 SELinux 或 AppArmor 實現強制訪問控制（MAC） | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160608 Implementing Mandatory Access Control with SELinux or AppArmor in Linux","title":"在 Linux 上用 SELinux 或 AppArmor 實現強制訪問控制（MAC）","tag":"201608","desc":""},"relativePath":"201608/20160608 Implementing Mandatory Access Control with SELinux or AppArmor in Linux.md","filePath":"[post].md"}'),u={name:"201608/20160608 Implementing Mandatory Access Control with SELinux or AppArmor in Linux.md"};function h(g,i,c,m,k,b){const t=o("Link");return r(),d("div",null,[i[34]||(i[34]=e("h1",{id:"在-linux-上用-selinux-或-apparmor-實現強制訪問控制-mac",tabindex:"-1"},[s("在 Linux 上用 SELinux 或 AppArmor 實現強制訪問控制（MAC） "),e("a",{class:"header-anchor",href:"#在-linux-上用-selinux-或-apparmor-實現強制訪問控制-mac","aria-label":"Permalink to “在 Linux 上用 SELinux 或 AppArmor 實現強制訪問控制（MAC）”"},"​")],-1)),e("p",null,[i[1]||(i[1]=s("為了解決標準的“用户-組-其他/讀-寫-執行”權限以及",-1)),a(t,{href:"http://www.tecmint.com/secure-files-using-acls-in-linux/"},{default:p(()=>[...i[0]||(i[0]=[s("訪問控制列表",-1)])]),_:1}),i[2]||(i[2]=s("的限制以及加強安全機制，美國國家安全局（NSA）設計出一個靈活的強制訪問控制（Mandatory Access Control：MAC）方法 SELinux（Security Enhanced Linux 的縮寫），來限制標準的權限之外的種種權限，在仍然允許對這個控制模型後續修改的情況下，讓進程儘可能以最小權限訪問或在系統對象（如文件，文件夾，網絡端口等）上執行其他操作。",-1))]),i[35]||(i[35]=n(`<p><img src="http://www.tecmint.com/wp-content/uploads/2016/06/SELinux-AppArmor-Security-Hardening-Linux.png" alt=""></p><p><em>SELinux 和 AppArmor 加固 Linux 安全</em></p><p>另一個流行並且被廣泛使用的 MAC 是 AppArmor，相比於 SELinux 它提供更多的特性，包括一個學習模式，可以讓系統“學習”一個特定應用的行為，以及通過配置文件設置限制實現安全的應用使用。</p><p>在 CentOS 7 中，SELinux 合併進了內核並且默認啓用強制（Enforcing）模式（下一節會介紹這方面更多的內容），與之不同的是，openSUSE 和 Ubuntu 使用的是 AppArmor 。</p><p>在這篇文章中我們會解釋 SELinux 和 AppArmor 的本質，以及如何在你選擇的發行版上使用這兩個工具之一併從中獲益。</p><h3 id="selinux-介紹以及如何在-centos-7-中使用" tabindex="-1">SELinux 介紹以及如何在 CentOS 7 中使用 <a class="header-anchor" href="#selinux-介紹以及如何在-centos-7-中使用" aria-label="Permalink to “SELinux 介紹以及如何在 CentOS 7 中使用”">​</a></h3><p>Security Enhanced Linux 可以以兩種不同模式運行：</p><ul><li>強制（Enforcing）：這種情況下，SELinux 基於 SELinux 策略規則拒絕訪問，策略規則是一套控制安全引擎的規則。</li><li>寬容（Permissive）：這種情況下，SELinux 不拒絕訪問，但如果在強制模式下會被拒絕的操作會被記錄下來。</li></ul><p>SELinux 也能被禁用。儘管這不是它的一個操作模式，不過也是一種選擇。但學習如何使用這個工具強過只是忽略它。時刻牢記這一點！</p><p>使用 <code>getenforce</code> 命令來顯示 SELinux 的當前模式。如果你想要更改模式，使用 <code>setenforce 0</code>（設置為寬容模式）或 <code>setenforce 1</code>（強制模式）。</p><p>因為這些設置重啓後就失效了，你需要編輯 <code>/etc/selinux/config</code> 配置文件並設置 <code>SELINUX</code> 變量為 <code>enforcing</code>、<code>permissive</code> 或 <code>disabled</code> ，保存設置讓其重啓後也有效：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/06/Enable-Disable-SELinux-Mode.png" alt=""></p><p><em>如何啓用和禁用 SELinux 模式</em></p><p>還有一點要注意，如果 <code>getenforce</code> 返回 Disabled，你得編輯 <code>/etc/selinux/config</code> 配置文件為你想要的操作模式並重啓。否則你無法利用 <code>setenforce</code> 設置（或切換）操作模式。</p><p><code>setenforce</code> 的典型用法之一包括在 SELinux 模式之間切換（從強制到寬容或相反）來定位一個應用是否行為不端或沒有像預期一樣工作。如果它在你將 SELinux 設置為寬容模式正常工作，你就可以確定你遇到的是 SELinux 權限問題。</p><p>有兩種我們使用 SELinux 可能需要解決的典型案例：</p><ul><li>改變一個守護進程監聽的默認端口。</li><li>給一個虛擬主機設置 /var/www/html 以外的文檔根路徑值。</li></ul><p>讓我們用以下例子來看看這兩種情況。</p><h4 id="例-1-更改-sshd-守護進程的默認端口" tabindex="-1">例 1：更改 sshd 守護進程的默認端口 <a class="header-anchor" href="#例-1-更改-sshd-守護進程的默認端口" aria-label="Permalink to “例 1：更改 sshd 守護進程的默認端口”">​</a></h4><p>大部分系統管理員為了加強服務器安全首先要做的事情之一就是更改 SSH 守護進程監聽的端口，主要是為了阻止端口掃描和外部攻擊。要達到這個目的，我們要更改 <code>/etc/ssh/sshd_config</code> 中的 Port 值為以下值（我們在這裏使用端口 9999 為例）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Port 9999</span></span></code></pre></div><p>在嘗試重啓服務並檢查它的狀態之後，我們會看到它啓動失敗：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl restart sshd</span></span>
<span class="line"><span># systemctl status sshd</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/06/Check-sshd-Service-Status.png" alt=""></p><p><em>檢查 SSH 服務狀態</em></p><p>如果我們看看 <code>/var/log/audit/audit.log</code>，就會看到 sshd 被 SELinux 阻止在端口 9999 上啓動，因為它是 JBoss 管理服務的保留端口（SELinux 日誌信息包含了詞語“AVC”，所以應該很容易把它同其他信息區分開來）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /var/log/audit/audit.log | grep AVC | tail -1</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/06/Check-Linux-Audit-Logs.png" alt=""></p><p><em>檢查 Linux 審計日誌</em></p><p>在這種情況下大部分人可能會禁用 SELinux，但我們不這麼做。我們會看到有個讓 SELinux 和監聽其他端口的 sshd 和諧共處的方法。首先確保你有 <code>policycoreutils-python</code> 這個包，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install policycoreutils-python</span></span></code></pre></div><p>查看 SELinux 允許 sshd 監聽的端口列表。在接下來的圖片中我們還能看到端口 9999 是為其他服務保留的，所以我們暫時無法用它來運行其他服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># semanage port -l | grep ssh</span></span></code></pre></div><p>當然我們可以給 SSH 選擇其他端口，但如果我們確定我們不會使用這台機器跑任何 JBoss 相關的服務，我們就可以修改 SELinux 已存在的規則，轉而給 SSH 分配那個端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># semanage port -m -t ssh_port_t -p tcp 9999</span></span></code></pre></div><p>這之後，我們就可以用前一個 <code>semanage</code> 命令檢查端口是否正確分配了，即使用 <code>-lC</code> 參數（list custom 的簡稱）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># semanage port -lC</span></span>
<span class="line"><span># semanage port -l | grep ssh</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/06/Assign-Port-to-SSH.png" alt=""></p><p><em>給 SSH 分配端口</em></p><p>我們現在可以重啓 SSH 服務並通過端口 9999 連接了。注意這個更改重啓之後依然有效。</p><h4 id="例-2-給一個虛擬主機設置-var-www-html-以外的文檔根路徑-documentroot" tabindex="-1">例 2：給一個虛擬主機設置 /var/www/html 以外的文檔根路徑（DocumentRoot） <a class="header-anchor" href="#例-2-給一個虛擬主機設置-var-www-html-以外的文檔根路徑-documentroot" aria-label="Permalink to “例 2：給一個虛擬主機設置 /var/www/html 以外的文檔根路徑（DocumentRoot）”">​</a></h4>`,41)),e("p",null,[i[4]||(i[4]=s("如果你需要用除 ",-1)),i[5]||(i[5]=e("code",null,"/var/www/html",-1)),i[6]||(i[6]=s(" 以外目錄作為文檔根目錄（DocumentRoot）",-1)),a(t,{href:"http://www.tecmint.com/apache-virtual-hosting-in-centos/"},{default:p(()=>[...i[3]||(i[3]=[s("設置一個 Apache 虛擬主機",-1)])]),_:1}),i[7]||(i[7]=s("（也就是説，比如 ",-1)),i[8]||(i[8]=e("code",null,"/websrv/sites/gabriel/public_html",-1)),i[9]||(i[9]=s("）：",-1))]),i[36]||(i[36]=n(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DocumentRoot “/websrv/sites/gabriel/public_html”</span></span></code></pre></div><p>Apache 會拒絕提供內容，因為 <code>index.html</code> 已經被標記為了 <code>default_t SELinux</code> 類型，Apache 無法訪問它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># wget http://localhost/index.html</span></span>
<span class="line"><span># ls -lZ /websrv/sites/gabriel/public_html/index.html</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/06/Labeled-default_t-SELinux-Type.png" alt=""></p><p><em>被標記為 default_t SELinux 類型</em></p><p>和之前的例子一樣，你可以用以下命令驗證這是不是 SELinux 相關的問題：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /var/log/audit/audit.log | grep AVC | tail -1</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/06/Check-Logs-for-SELinux-Issues.png" alt=""></p><p><em>檢查日誌確定是不是 SELinux 的問題</em></p><p>要將 <code>/websrv/sites/gabriel/public_html</code> 整個目錄內容標記為 <code>httpd_sys_content_t</code>，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># semanage fcontext -a -t httpd_sys_content_t &quot;/websrv/sites/gabriel/public_html(/.*)?&quot;</span></span></code></pre></div><p>上面這個命令會賦予 Apache 對那個目錄以及其內容的讀取權限。</p><p>最後，要應用這條策略（並讓更改的標記立即生效），執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># restorecon -R -v /websrv/sites/gabriel/public_html</span></span></code></pre></div><p>現在你應該可以訪問這個目錄了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># wget http://localhost/index.html</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/06/Access-Apache-Directory.png" alt=""></p><p><em>訪問 Apache 目錄</em></p>`,18)),e("p",null,[i[11]||(i[11]=s("要獲取關於 SELinux 的更多信息，參閲 Fedora 22 中的 ",-1)),a(t,{href:"https://docs.fedoraproject.org/en-US/Fedora/22/html/SELinux_Users_and_Administrators_Guide/index.html"},{default:p(()=>[...i[10]||(i[10]=[s("SELinux 用户及管理員指南",-1)])]),_:1}),i[12]||(i[12]=s("。",-1))]),i[37]||(i[37]=n('<h3 id="apparmor-介紹以及如何在-opensuse-和-ubuntu-上使用它" tabindex="-1">AppArmor 介紹以及如何在 OpenSUSE 和 Ubuntu 上使用它 <a class="header-anchor" href="#apparmor-介紹以及如何在-opensuse-和-ubuntu-上使用它" aria-label="Permalink to “AppArmor 介紹以及如何在 OpenSUSE 和 Ubuntu 上使用它”">​</a></h3><p>AppArmor 的操作是基於寫在純文本文件中的規則定義，該文件中含有允許權限和訪問控制規則。安全配置文件用來限制應用程序如何與系統中的進程和文件進行交互。</p><p>系統初始就提供了一系列的配置文件，但其它的也可以由應用程序在安裝的時候設置或由系統管理員手動設置。</p><p>像 SELinux 一樣，AppArmor 以兩種模式運行。在 enforce 模式下，應用被賦予它們運行所需要的最小權限，但在 complain 模式下 AppArmor 允許一個應用執行受限的操作並將操作造成的“抱怨”記錄到日誌裏（<code>/var/log/kern.log</code>，<code>/var/log/audit/audit.log</code>，和其它放在 <code>/var/log/apparmor</code> 中的日誌）。</p><p>日誌中會顯示配置文件在強制模式下運行時會產生錯誤的記錄，它們中帶有 <code>audit</code> 這個詞。因此，你可以在 AppArmor 的 enforce 模式下運行之前，先在 complain 模式下嘗試運行一個應用並調整它的行為。</p><p>可以用這個命令顯示 AppArmor 的當前狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apparmor_status</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/06/Check-AppArmor-Status.png" alt=""></p><p><em>查看 AppArmor 的狀態</em></p><p>上面的圖片指明配置 <code>/sbin/dhclient</code>，<code>/usr/sbin/</code>，和 <code>/usr/sbin/tcpdump</code> 等處在 enforce 模式下（在 Ubuntu 下默認就是這樣的）。</p><p>因為不是所有的應用都包含相關的 AppArmor 配置，apparmor-profiles 包給其它沒有提供限制的包提供了配置。默認它們配置在 complain 模式下運行，以便系統管理員能夠測試並選擇一個所需要的配置。</p>',11)),e("p",null,[i[14]||(i[14]=s("我們將會利用 apparmor-profiles，因為寫一份我們自己的配置已經超出了 LFCS ",-1)),a(t,{href:"http://www.tecmint.com/sed-command-to-create-edit-and-manipulate-files-in-linux/"},{default:p(()=>[...i[13]||(i[13]=[s("認證",-1)])]),_:1}),i[15]||(i[15]=s("的範圍了。但是，由於配置都是純文本文件，你可以查看並學習它們，為以後創建自己的配置做準備。",-1))]),i[38]||(i[38]=n('<p>AppArmor 配置保存在 <code>/etc/apparmor.d</code> 中。讓我們來看看這個文件夾在安裝 apparmor-profiles 之前和之後有什麼不同：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /etc/apparmor.d</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/06/View-AppArmor-Directory-Content.png" alt=""></p><p><em>查看 AppArmor 文件夾內容</em></p><p>如果你再次執行 <code>sudo apparmor_status</code>，你會在 complain 模式看到更長的配置文件列表。你現在可以執行下列操作。</p><p>將當前在 enforce 模式下的配置文件切換到 complain 模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo aa-complain /path/to/file</span></span></code></pre></div><p>以及相反的操作（complain –&gt; enforce）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo aa-enforce /path/to/file</span></span></code></pre></div><p>上面這些例子是允許使用通配符的。舉個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo aa-complain /etc/apparmor.d/*</span></span></code></pre></div><p>會將 <code>/etc/apparmor.d</code> 中的所有配置文件設置為 complain 模式，反之</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo aa-enforce /etc/apparmor.d/*</span></span></code></pre></div><p>會將所有配置文件設置為 enforce 模式。</p><p>要完全禁用一個配置，在 <code>/etc/apparmor.d/disabled</code> 目錄中創建一個符號鏈接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ln -s /etc/apparmor.d/profile.name /etc/apparmor.d/disable/</span></span></code></pre></div>',16)),e("p",null,[i[18]||(i[18]=s("要獲取關於 AppArmor 的更多信息，參閲",-1)),a(t,{href:"http://wiki.apparmor.net/index.php/Main_Page"},{default:p(()=>[...i[16]||(i[16]=[s("官方的 AppArmor wiki",-1)])]),_:1}),i[19]||(i[19]=s(" 以及 ",-1)),a(t,{href:"https://help.ubuntu.com/community/AppArmor"},{default:p(()=>[...i[17]||(i[17]=[s("Ubuntu 提供的",-1)])]),_:1}),i[20]||(i[20]=s("文檔。",-1))]),i[39]||(i[39]=e("h3",{id:"總結",tabindex:"-1"},[s("總結 "),e("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),i[40]||(i[40]=e("p",null,"在這篇文章中我們學習了一些 SELinux 和 AppArmor 這兩個著名的強制訪問控制系統的基本知識。什麼時候使用兩者中的一個或是另一個？為了避免提高難度，你可能需要考慮專注於你選擇的發行版自帶的那一個。不管怎樣，它們會幫助你限制進程和系統資源的訪問，以提高你服務器的安全性。",-1)),i[41]||(i[41]=e("p",null,"關於本文你有任何的問題，評論，或建議，歡迎在下方發表。不要猶豫，讓我們知道你是否有疑問或評論。",-1)),i[42]||(i[42]=e("hr",null,null,-1)),e("p",null,[i[22]||(i[22]=s("via: ",-1)),a(t,{href:"http://www.tecmint.com/mandatory-access-control-with-selinux-or-apparmor-linux/"},{default:p(()=>[...i[21]||(i[21]=[s("http://www.tecmint.com/mandatory-access-control-with-selinux-or-apparmor-linux/",-1)])]),_:1})]),e("p",null,[i[26]||(i[26]=s("作者：",-1)),a(t,{href:"http://www.tecmint.com/author/gacanepa/"},{default:p(()=>[...i[23]||(i[23]=[s("Gabriel Cánepa",-1)])]),_:1}),i[27]||(i[27]=s(" 譯者：",-1)),a(t,{href:"https://github.com/alim0x"},{default:p(()=>[...i[24]||(i[24]=[s("alim0x",-1)])]),_:1}),i[28]||(i[28]=s(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:p(()=>[...i[25]||(i[25]=[s("wxy",-1)])]),_:1})]),e("p",null,[i[31]||(i[31]=s("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...i[29]||(i[29]=[s("LCTT",-1)])]),_:1}),i[32]||(i[32]=s(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:p(()=>[...i[30]||(i[30]=[s("Linux中國",-1)])]),_:1}),i[33]||(i[33]=s(" 榮譽推出",-1))])])}const w=l(u,[["render",h]]);export{A as __pageData,w as default};
